const articles = [
  {
    title: 'VPN Connection Issues - Timeout Errors',
    content: 'Users experiencing VPN timeout errors. Common causes include: expired certificates, network firewall blocks, incorrect VPN client version, or ISP throttling.',
    category: 'Network',
    subcategory: 'VPN',
    tags: ['vpn', 'timeout', 'connection', 'network'],
    resolution_steps: '1. Check VPN client version\n2. Verify certificates\n3. Try different network\n4. Check firewall settings',
    priority_hint: '2-High',
    assignment_group: 'Network Operations'
  },
  {
    title: 'Password Reset Request',
    content: 'User needs password reset for corporate account. Self-service portal available at password.company.com.',
    category: 'Access',
    subcategory: 'Password',
    tags: ['password', 'reset', 'access'],
    resolution_steps: '1. Direct to self-service portal\n2. Verify identity\n3. Unlock in AD\n4. Force password reset',
    priority_hint: '3-Medium',
    assignment_group: 'Identity Management'
  }
];

return articles.map(a => ({ json: a }));

const items = $input.all();
let rawArticles = [];

for (const item of items) {
  const data = item.json;
  if (data.articles && Array.isArray(data.articles)) {
    rawArticles.push(...data.articles);
  } else if (Array.isArray(data)) {
    rawArticles.push(...data);
  } else if (data.title && data.content) {
    rawArticles.push(data);
  }
}

const articles = rawArticles
  .filter(a => a && a.title && a.content)
  .map(a => ({
    title: String(a.title).trim(),
    content: String(a.content).trim(),
    category: a.category || 'General',
    subcategory: a.subcategory || '',
    tags: Array.isArray(a.tags) ? `{${a.tags.join(',')}}` : (a.tags ? `{${a.tags}}` : '{}'),
    resolution_steps: Array.isArray(a.resolution_steps) ? a.resolution_steps.join('\n') : (a.resolution_steps || ''),
    priority_hint: a.priority_hint || '3-Medium',
    assignment_group: a.assignment_group || 'IT Support'
  }));

if (articles.length === 0) {
  throw new Error('No valid articles found');
}

return articles.map(article => ({ json: article }));

const supabaseItems = $input.all();

const originalArticles = $('Process Articles').all().map(i => i.json);

return [
  ...supabaseItems.map((item, idx) => ({ json: item.json, pairedItem: { item: idx } })),
  { json: { _articles: originalArticles }, pairedItem: { item: 0 } }
];

const existingTitlesData = $input.all();
const existingTitles = new Set();

for (const item of existingTitlesData) {
  if (item.json.title && !item.json._articles) {
    existingTitles.add(item.json.title);
  }
}

const articlesItem = existingTitlesData.find(i => i.json._articles);
if (!articlesItem || !articlesItem.json._articles) {
  throw new Error('No articles data found');
}

const inputArticles = articlesItem.json._articles;
const newArticles = inputArticles.filter(a => !existingTitles.has(a.title));

if (newArticles.length === 0) {
  throw new Error(`No new articles to insert. All ${inputArticles.length} articles already exist in KB.`);
}

console.log(`Found ${newArticles.length} new articles out of ${inputArticles.length} total`);

// Pass complete article data through
return newArticles.map((a, index) => ({ 
  json: { 
    _article: a,
    content: a.content
  }
}));

const embeddings = $input.all();
const articles = $('Filter Duplicates').all();

return embeddings.map((item, idx) => {
  const article = articles[idx]?.json?._article || {};
  const embedding = item.json?.data?.[0]?.embedding || [];

  return {
    json: {
      title: article.title || '',
      content: article.content || '',
      category: article.category || 'General',
      subcategory: article.subcategory || '',
      tags: article.tags || '{}',
      resolution_steps: article.resolution_steps || '',
      priority_hint: article.priority_hint || '3-Medium',
      assignment_group: article.assignment_group || 'IT Support',
      embedding: embedding
    }
  };
});
